/* Per-course tuition controls and named navigation. */
const reviewBeforeTuitionPolish=reviewEnrollment;
reviewEnrollment=function(id){reviewBeforeTuitionPolish(id);if(!admin)return;const fields=$('fields');
 const enhance=box=>{if(box.dataset.tuitionBound)return;box.dataset.tuitionBound='true';const index=[...fields.querySelectorAll('.review-extra-course')].indexOf(box),prefix='course_'+index+'_',section=document.createElement('fieldset');section.className='tuition-setup';section.innerHTML='<legend>شهریهٔ مستقل این کلاس</legend><p class="sub">وضعیت پرداخت این چهار جلسه فقط برای همین استاد ثبت می‌شود.</p><div class="tuition-controls"></div>';const grid=section.querySelector('div');
 for(const key of ['month_key','p1','p2','p3','p4','note']){const source=$('form').elements[key],label=source.closest('label').cloneNode(true),input=label.querySelector('select,input,textarea');input.name=prefix+key;input.dataset.tuitionKey=key;input.removeAttribute('id');label.querySelectorAll('small').forEach(x=>x.remove());if(key==='month_key'||key==='note')label.classList.add('full-field');if(/^p/.test(key))input.value='false';if(key==='note')input.value='';grid.append(label)}box.append(section);
 const update=()=>{const month=box.querySelector('[data-tuition-key="month_key"]').value,day=box.querySelector('[data-course-key="weekday"]').value,dates=tuitionDates(month,day);for(let i=1;i<=4;i++){const label=box.querySelector('[data-tuition-key="p'+i+'"]').closest('label');let small=label.querySelector('small');if(!small){small=document.createElement('small');label.append(small)}small.textContent=dates[i-1]?AcademyDates.show(dates[i-1]):''}};box.addEventListener('change',update);update();};
 fields.querySelectorAll('.review-extra-course').forEach(enhance);const observer=new MutationObserver(()=>fields.querySelectorAll('.review-extra-course').forEach(enhance));observer.observe(fields,{childList:true});modal.addEventListener('close',()=>observer.disconnect(),{once:true});
};
const apiBeforeIndependentReview=api;
api=async function(path,method='GET',body){if(path==='/rest/v1/rpc/approve_enrollment_with_tuition'&&method==='POST'){
 const extras=[...$('fields').querySelectorAll('.review-extra-course')].map(box=>{const data=Object.fromEntries([...box.querySelectorAll('[data-course-key]')].map(el=>[el.dataset.courseKey,el.value]));for(const key of ['month_key','note'])data[key]=box.querySelector('[data-tuition-key="'+key+'"]').value;data.paid=[1,2,3,4].map(i=>box.querySelector('[data-tuition-key="p'+i+'"]').value==='true');return data});
 const d=body.data;return enrollmentApiOneCourse('/rest/v1/rpc/approve_multi_enrollment',method,{data:{...d,courses:[{teacher_id:d.teacher_id,subject:d.subject,weekday:d.weekday,class_time:d.class_time,month_key:d.month_key,paid:d.paid,note:d.note},...extras]}});
 }return apiBeforeIndependentReview(path,method,body)};
function jumpToLearnerTuition(id){go('monthly');requestAnimationFrame(()=>{const el=document.getElementById('tuition-learner-'+id);if(el){el.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});el.focus({preventScroll:true})}})}
const monthlyBeforeNamedNavigation=views.monthly;
views.monthly=function(){const html=monthlyBeforeNamedNavigation();if(!office)return html;const holder=document.createElement('div');holder.innerHTML=html;const list=db.students.filter(s=>monthRows.some(t=>t.student_id===s.id));const cards=[...holder.querySelectorAll('.card')].filter(c=>c.querySelector('.tuition-months'));
 cards.forEach((card,i)=>{if(!list[i])return;card.id='tuition-learner-'+list[i].id;card.tabIndex=-1;card.classList.add('tuition-learner-section');const heading=card.querySelector('h3');if(heading)heading.textContent=full(list[i])+' · '+classLabel(list[i]);});
 for(const s of db.students.filter(s=>!s.archived_at&&!list.some(c=>c.id===s.id))){const card=document.createElement('section');card.className='card tuition-learner-section';card.id='tuition-learner-'+s.id;card.tabIndex=-1;card.innerHTML='<h3>'+esc(full(s))+' · '+esc(classLabel(s))+'</h3><p>شهریهٔ این کلاس هنوز تنظیم نشده است.</p>'+(admin?'<button onclick="editMonth(\''+s.id+'\')">تنظیم شهریهٔ این کلاس</button>':'');holder.append(card);list.push(s)}const nav=document.createElement('nav');nav.className='learner-jump-list';nav.setAttribute('aria-label','رفتن به شهریهٔ هنرجو');nav.innerHTML='<strong>هنرجو را انتخاب کنید</strong>'+list.map(s=>'<button type="button" onclick="jumpToLearnerTuition(\''+s.id+'\')"><span>'+esc(full(s))+'</span><small>'+esc(s.subject)+' · '+esc(teacher(s.teacher_id))+'</small><b aria-hidden="true">↓</b></button>').join('');if(list.length){const title=holder.querySelector('.title');if(title)title.after(nav);else holder.prepend(nav)}return holder.innerHTML};
const studentTableBeforeNamedLinks=studentTable;
studentTable=function(list){const holder=document.createElement('div');holder.innerHTML=studentTableBeforeNamedLinks(list);learnerGroups(list).forEach((courses,i)=>{const row=holder.querySelectorAll('tbody tr')[i],name=row?.querySelector('td b');if(!name)return;const button=document.createElement('button');button.className='learner-name-link';button.type='button';button.textContent=full(courses[0]);button.setAttribute('onclick',"jumpToLearnerTuition('"+courses[0].id+"')");name.replaceWith(button)});return holder.innerHTML};
render();
